const j = $input.first().json;
const headers = j.headers || {};
const key = String($env.CASTUO_ORCHESTRATOR_KEY || '').trim();
if (key) {
  const got = String(headers['x-api-key'] || headers['X-API-Key'] || '');
  if (got !== key) throw new Error('X-API-Key inválida');
}
const body = j.body && typeof j.body === 'object' && !Array.isArray(j.body) ? j.body : j;
const request_type = body.request_type;
const data = body.data;
if (!request_type || !data || typeof data !== 'object') {
  throw new Error('Cuerpo JSON: { request_type, data }');
}
let payload;
switch (String(request_type)) {
  case 'sensores':
    payload = { kind: 'iot_sensor', ...data };
    break;
  case 'qelectrotech':
    payload = { kind: 'qelectrotech_svg', ...data };
    if (!payload.svg_base64) throw new Error('data.svg_base64 requerido');
    break;
  case 'plc':
  case 'cursor_mcp':
    payload = {
      kind: 'plc_generate',
      project_id: data.project_id,
      requirements: data.requirements || data.description || '',
      hardware: data.hardware || 'S7-1200',
      standards: data.standards || ['IEC 61131-3'],
    };
    break;
  case 'simulacion':
    payload = { ...data };
    delete payload.kind;
    break;
  default:
    throw new Error('request_type no soportado: ' + request_type);
}
return [{ json: { payload, request_type, received_at: new Date().toISOString() } }];

const lg = $input.first().json;
const meta = $('Classify_And_Build_Payload').first().json;
if (lg.errors && lg.errors.length) {
  throw new Error('LangGraph: ' + lg.errors.join('; '));
}
return [
  {
    json: {
      ok: true,
      request_type: meta.request_type,
      trace_hash: lg.trace_hash || '',
      analysis: lg.analysis || '',
      gaia_http_status: lg.gaia_http_status,
      gaia_body: lg.gaia_body,
      slack_http_status: lg.slack_http_status,
      received_at: meta.received_at,
    },
  },
];
